package com.vandorlabs.gear.core;
import java.util.*;import com.vandorlabs.ui.*;
public final class ArmAnglePolicyChecks {
 private static int checks;private static void need(boolean yes,String message){checks++;if(!yes)throw new AssertionError(message);}
 private static boolean same(double a,double b){return Double.doubleToLongBits(a)==Double.doubleToLongBits(b);}
 public static void main(String[] args){
  ArmLandingAngles old=new ArmLandingAngles(-1,45,135);need(old.start(true)==0&&old.end(true)==90&&old.rawStart==45&&old.rawEnd==135,"legacy physical angles ignore and preserve raw remnants");need(old.start(false)==45&&old.end(false)==135,"ordinary payload angles unchanged");ArmLandingAngles copied=old.copied(true);need(copied.configured()&&copied.rawStart==0&&copied.rawEnd==90,"legacy landing semantic copy exports actual physical endpoints");ArmLandingAngles edit=old.edit(true,true,15);need(edit.configured()&&edit.rawStart==15&&edit.rawEnd==90,"first Start edit initializes End from physical90");edit=old.edit(true,false,30);need(edit.rawStart==0&&edit.rawEnd==30,"first End edit initializes Start from physical0");need(ArmLandingAngles.version(false,false,99)==-1,"absent marker remains absent");for(int value:new int[]{-1,2,999}){boolean refused=false;try{ArmLandingAngles.version(true,true,value);}catch(IllegalArgumentException expected){refused=true;}need(refused,"unknown landing-angle version refuses "+value);}boolean wrong=false;try{ArmLandingAngles.version(true,false,1);}catch(IllegalArgumentException expected){wrong=true;}need(wrong,"wrong marker type refuses");
  double[] a=new double[3],b=new double[3];int profiles=0;
  for(int width=1;width<=2;width++)for(int height:new int[]{1,2,8})for(double socket:new double[]{0,9/16D,11/16D})for(ArmHinge.Mode hinge:ArmHinge.Mode.values())for(GearMotion.Direction fold:GearMotion.Direction.values())for(GearMotion.Direction kink:GearMotion.Direction.values())for(GearMotion.Mode mode:new GearMotion.Mode[]{GearMotion.Mode.ROTATE,GearMotion.Mode.ROTATE_LEVEL}){
   double drop=mode==GearMotion.Mode.ROTATE_LEVEL&&width==2&&socket==11/16D&&hinge==ArmHinge.Mode.SINGLE?17/128D:0;GearFootProjection legacy=new GearFootProjection(),physical=new GearFootProjection();for(int tick=0;tick<=32;tick++){double phase=tick/32D;legacy.prepare(mode,fold,height,phase,GearMotion.RETRACTED_FOOT_Y,drop,socket,90,0,hinge,kink,width);physical.prepare(mode,fold,height,phase,GearMotion.RETRACTED_FOOT_Y,drop,socket,old.end(true),old.start(true),hinge,kink,width);for(int corner=0;corner<8;corner++){legacy.write(corner&1,-height+((corner>>1)&1),(corner>>2)&1,a,0);physical.write(corner&1,-height+((corner>>1)&1),(corner>>2)&1,b,0);for(int axis=0;axis<3;axis++)need(same(a[axis],b[axis]),"old midstroke physical pose exact");}}
   List<GearTopology.Cell> feet=Arrays.asList(new GearTopology.Cell(0,-height,0),new GearTopology.Cell(1,-height,0));LandingAnglePolicy.Result result=LandingAnglePolicy.evaluate(mode,fold,height,width,GearMotion.RETRACTED_FOOT_Y,drop,socket,hinge,kink,old,feet);need(result.nativeAt(1),"legacy Start0 retains actual grid foot endpoint");need(result.valid(),"old landing still has at least one native endpoint");need(result.safeTarget(true)==1,"old automatic ground target remains Start");profiles++;
  }
  List<GearTopology.Cell> feet=Collections.singletonList(new GearTopology.Cell(0,-2,0));LandingAnglePolicy.Result invalid=LandingAnglePolicy.evaluate(GearMotion.Mode.ROTATE,GearMotion.Direction.NORTH,2,1,GearMotion.RETRACTED_FOOT_Y,0,0,ArmHinge.Mode.SINGLE,GearMotion.Direction.NORTH,new ArmLandingAngles(1,45,135),feet);need(!invalid.valid(),"two non-native endpoints refuse");LandingAnglePolicy.Result alternative=LandingAnglePolicy.evaluate(GearMotion.Mode.ROTATE_LEVEL,GearMotion.Direction.NORTH,2,1,GearMotion.RETRACTED_FOOT_Y,0,0,ArmHinge.Mode.SINGLE,GearMotion.Direction.NORTH,new ArmLandingAngles(1,45,0),feet);need(alternative.nativeAt(0)&&!alternative.nativeAt(1)&&alternative.safeTarget(true)==0,"valid End0 can be sole safe landing target");LandingAnglePolicy.Result quarter=LandingAnglePolicy.evaluate(GearMotion.Mode.ROTATE_LEVEL,GearMotion.Direction.NORTH,2,1,GearMotion.RETRACTED_FOOT_Y,0,0,ArmHinge.Mode.SINGLE,GearMotion.Direction.NORTH,new ArmLandingAngles(1,90,90),feet);need(!quarter.valid(),"quarter-turn angles alone do not establish integral socket translation");
  for(int w:new int[]{320,380,640})for(int h:new int[]{200,220,240,270,480})for(int kind=0;kind<4;kind++)for(boolean landing:new boolean[]{false,true}){GearDialog.Panel p=new GearDialog.Panel(w,h);GearDialog.State s=new GearDialog.State();s.rotating=kind==0;s.fixed=kind==1;s.landing=landing;s.canFoot=landing;s.rest=s.atEndpoint=s.hingeEditable=true;s.canJoin=!landing&&!s.fixed;s.canCarry=!s.rotating&&!s.fixed&&!landing;s.canPush=s.canCarry;s.join=s.carry=true;s.joinRange=32;s.loadHeight=16;s.start=0;s.end=90;s.track=landing?"Bogie":null;for(int page=0;page<=1;page++){List<GearDialog.Control> cs=GearDialog.controls(p,s,page);Set<Integer> ids=new HashSet<Integer>();for(GearDialog.Control c:cs){need(ids.add(c.id),"unique logical control");need(c.x>=0&&c.y>=0&&c.x+c.width<=p.width&&c.y+c.height<=p.height,"bounded compact controls");for(GearDialog.Control d:cs)if(c.id<d.id)need(c.x+c.width<=d.x||d.x+d.width<=c.x||c.y+c.height<=d.y||d.y+d.height<=c.y,"no control overlap");}if(page==0&&s.rotating)need(ids.contains(13)&&ids.contains(16),"both angle sliders visible with or without landing feet");if(page==0&&s.canJoin)need(ids.contains(9)&&ids.contains(10),"join and explicitly named range paired");if(page==1)need(ids.contains(0)&&ids.contains(GearDialog.CHANNELS)&&!ids.contains(10),"standard Redstone page has activation/channel only");}}
  System.out.println("Arm angle policy draft PASS profiles="+profiles+" checks="+checks);
 }
}
